    "description": "Embassy Springs in Devanahalli, Bangalore North, is an upcoming residential project offering thoughtfully designed apartments for modern living. Set within a well-planned community, the society provides all essential amenities, including a swimming pool, gymnasium, and clubhouse, ensuring comfort and convenience for every resident. Embassy Springs promises a balanced lifestyle with contemporary architecture and a vibrant, connected neighborhood.",
    "builderDescription": "Embassy Property Developments Private Limited commenced operations in 1993. Together with our promoters we have 29 years of experience in real estate development. Embassy has an extensive land bank across the country and has developed close to 35 million square feet of prime commercial, residential and retail space as of March 2014. We also have international operations in Malaysia and Serbia.\r\n\r\nOur portfolio of real estate developments spans the commercial, residential, retail and hospitality segments of the real estate industry. Our commercial real estate business includes the development of business parks for the IT/ITES sector, SEZs and corporate office space. The majority of the completed projects in our commercial portfolio are built-to-suit and fit-out developments undertaken for specific clients.\r\nGoing forward, we intend to undertake a combination of built-to-suit projects and those done without pre-commitment. Our clients include Alcatel-Lucent, Atos Origin, ANZ, Cognizant, Computer Science Corporation, Fidelity, Geometric, IBM, LG Soft India, McAfee, Mercedes-Benz, Microsoft, NetApp, Nokia Siemens Networks, Supervalu, Target, Vodafone and Yahoo\r\nOver the last 29 years, Embassy has completed over 5.9 million sft. of residential spaces. Embassy?s ongoing residential projects include luxury apartments and integrated townships. Embassy?s residential projects are also designed to obtain IGBC Green Homes Certifications ratings as part of the efforts for creating sustainable developments.",
