    "builderDescription": "Radiance Realty, a leading real estate player based in Chennai, is built on a legacy of tradition and is driven by the verve and vigour of youth. A formidable force in the Indian real estate industry with a nationwide presence, Radiance Realty is dedicated to providing premium housing solutions designed for the 21st century and is committed to exceed customers’ expectations.\r\nEvery project of Radiance Realty is designed and built on a strong foundation of customer centric innovation and perfection. Featuring the latest amenities and the most modern designs, it focusses on delivering luxurious lifestyle options that are suited to the discerning homeowner. With the promoters having a background of over 70 years of experience in construction, Radiance Realty has been a welcome part of many new beginnings and hopes to be a part of yours as well.\r\n\r\n\r\n",
